import React from "react";
import { Button } from "react-bootstrap";

const EsportaCSV = ({ dati, nomeFile = "report_interventi.csv" }) => {
  const esporta = () => {
    if (!dati || dati.length === 0) {
      alert("⚠️ Nessun dato da esportare.");
      return;
    }

    const intestazioni = Object.keys(dati[0]);
    const righe = dati.map(row =>
      intestazioni.map(col => `"${(row[col] ?? "").toString().replace(/"/g, '""')}"`).join(",")
    );

    const csv = [intestazioni.join(","), ...righe].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.setAttribute("download", nomeFile);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <Button variant="success" onClick={esporta}>
      📤 Esporta CSV
    </Button>
  );
};

export default EsportaCSV;